import torch
import torch.distributed as dist
import torch.nn as nn
import torch.nn.functional as F


def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


# ---------------------------------------------------------------------------
# Autograd-aware communication primitives
# ---------------------------------------------------------------------------
class _CopyToParallelRegion(torch.autograd.Function):
    """Identity in forward, all-reduce of the gradient in backward."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad):
        if _world_size() == 1:
            return grad
        grad = grad.contiguous().clone()
        dist.all_reduce(grad, op=dist.ReduceOp.SUM)
        return grad


class _ReduceFromParallelRegion(torch.autograd.Function):
    """All-reduce (sum) in forward, identity in backward."""

    @staticmethod
    def forward(ctx, x):
        if _world_size() == 1:
            return x
        x = x.contiguous().clone()
        dist.all_reduce(x, op=dist.ReduceOp.SUM)
        return x

    @staticmethod
    def backward(ctx, grad):
        return grad


class _ScatterToParallelRegion(torch.autograd.Function):
    """Take the local chunk of the last dim in forward, all-gather in backward."""

    @staticmethod
    def forward(ctx, x):
        ws = _world_size()
        if ws == 1:
            return x
        chunk = x.shape[-1] // ws
        r = _rank()
        return x[..., r * chunk:(r + 1) * chunk].contiguous()

    @staticmethod
    def backward(ctx, grad):
        return _gather_last_dim(grad)


class _GatherFromParallelRegion(torch.autograd.Function):
    """All-gather along the last dim in forward, take local chunk in backward."""

    @staticmethod
    def forward(ctx, x):
        return _gather_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        ws = _world_size()
        if ws == 1:
            return grad
        chunk = grad.shape[-1] // ws
        r = _rank()
        return grad[..., r * chunk:(r + 1) * chunk].contiguous()


def _gather_last_dim(x):
    ws = _world_size()
    if ws == 1:
        return x
    x = x.contiguous()
    parts = [torch.empty_like(x) for _ in range(ws)]
    dist.all_gather(parts, x)
    return torch.cat(parts, dim=-1).contiguous()


# ---------------------------------------------------------------------------
# Parallel linear layers
# ---------------------------------------------------------------------------
class ColumnParallelLinear(nn.Module):
    """Y = X A^T + b with A (out_features x in_features) split along the output
    dimension (i.e. the columns of A^T). Outputs are all-gathered along the
    last dimension."""

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.world_size = _world_size()
        self.rank = _rank()
        assert out_features % self.world_size == 0, \
            "out_features must be divisible by world_size"
        self.in_features = in_features
        self.out_features = out_features
        self.out_features_per_partition = out_features // self.world_size

        master_weight = torch.as_tensor(master_weight).detach()
        assert tuple(master_weight.shape) == (out_features, in_features), \
            f"master_weight must have shape {(out_features, in_features)}"
        start = self.rank * self.out_features_per_partition
        end = start + self.out_features_per_partition
        self.weight = nn.Parameter(master_weight[start:end, :].clone().contiguous())

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(self.out_features_per_partition,
                            dtype=self.weight.dtype, device=self.weight.device))
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        x = _CopyToParallelRegion.apply(x)
        y_local = F.linear(x, self.weight, self.bias)
        return _GatherFromParallelRegion.apply(y_local)


class RowParallelLinear(nn.Module):
    """Y = X A^T + b with A (out_features x in_features) split along the input
    dimension (i.e. the rows of A^T). Partial outputs are all-reduced (summed)
    and the full bias is added on each rank."""

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.world_size = _world_size()
        self.rank = _rank()
        assert in_features % self.world_size == 0, \
            "in_features must be divisible by world_size"
        self.in_features = in_features
        self.out_features = out_features
        self.in_features_per_partition = in_features // self.world_size

        master_weight = torch.as_tensor(master_weight).detach()
        assert tuple(master_weight.shape) == (out_features, in_features), \
            f"master_weight must have shape {(out_features, in_features)}"
        start = self.rank * self.in_features_per_partition
        end = start + self.in_features_per_partition
        self.weight = nn.Parameter(master_weight[:, start:end].clone().contiguous())

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(out_features,
                            dtype=self.weight.dtype, device=self.weight.device))
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        # Accept either the full input or an already-partitioned input.
        if self.world_size > 1 and x.shape[-1] == self.in_features:
            x = _ScatterToParallelRegion.apply(x)
        y_partial = F.linear(x, self.weight)
        y = _ReduceFromParallelRegion.apply(y_partial)
        if self.bias is not None:
            y = y + self.bias
        return y
